// labelIdx: 0=Watch, 1=Stopwatch(timer), 2=Pomodoro, 3=Weather(cloud-sun), 4=Configuration(cog), 5=WiFi(status)
inline const unsigned char* menuIconBitmap(uint8_t labelIdx, uint8_t size,
                                        uint8_t* outW, uint8_t* outH) {
  switch (labelIdx) {
    case 0:  // Watch
      if (size == 48) { *outW = 48; *outH = 48; return ICON_WATCH_48; }
      if (size == 32) { *outW = 32; *outH = 32; return ICON_WATCH_32; }
      break;
    case 1:  // Stopwatch (timer glyph)
      if (size == 48) { *outW = 48; *outH = 48; return ICON_TIMER_48; }
      if (size == 32) { *outW = 32; *outH = 32; return ICON_TIMER_32; }
      break;
    case 2:  // Pomodoro
      if (size == 48) { *outW = 48; *outH = 48; return ICON_POMODORO_48; }
      if (size == 32) { *outW = 32; *outH = 32; return ICON_POMODORO_32; }
      break;
    case 3:  // Weather (cloud-sun)
      if (size == 48) { *outW = 48; *outH = 48; return ICON_CLOUD_SUN_48; }
      if (size == 32) { *outW = 32; *outH = 32; return ICON_CLOUD_SUN_32; }
      break;
    case 4:  // Configuration (cog glyph)
      if (size == 48) { *outW = 48; *outH = 48; return ICON_COG_48; }
      if (size == 32) { *outW = 32; *outH = 32; return ICON_COG_32; }
      break;
    case 5:  // WiFi (status indicator)
      if (size == 48) { *outW = 48; *outH = 48; return ICON_WIFI_48; }
      if (size == 32) { *outW = 32; *outH = 32; return ICON_WIFI_32; }
      break;
  }
  *outW = 0; *outH = 0;
  return nullptr;
}

